1	// Package chainledger implements the on-chain data governance core.
2	package chainledger
3	
4	import "sort"
5	
6	// Dataset is one ingestible on-chain data source with a declared schema version.
7	type Dataset struct {
8		Name          string
9		SchemaVersion int
10		Rows          int
11		Upstreams     []string
12	}
13	
14	// Lineage records where a dataset came from, so every derived table can be traced.
15	type Lineage struct {
16		Dataset  string
17		Parents  []string
18		Children []string
19	}
20	
21	// Register links a dataset into the lineage graph and rejects cycles.
22	//
23	// Re-registering an existing dataset replaces its direct upstreams with parents
24	// (de-duplicated, first occurrence wins, list order preserved) while keeping its
25	// existing direct downstreams. Reverse edges stay consistent: upstreams removed
26	// from the list drop the dataset from their children, newly added upstreams gain
27	// it at the end of their children, and retained upstreams keep exactly one entry
28	// in its original position.
29	//
30	// The whole request is validated before the graph is touched, so a rejected
31	// registration leaves every node, edge and ordering untouched. The parents slice
32	// is copied: mutating it after Register returns does not affect the graph.
33	func Register(graph map[string]*Lineage, dataset Dataset, parents []string) error {
34		if dataset.Name == "" {
35			return errInvalid("dataset name is required")
36		}
37	
38		// Validate up front, walking the request in input order so the first problem
39		// encountered is the one reported. No graph mutation happens in this loop.
40		upstreams := make([]string, 0, len(parents))
41		known := map[string]bool{}
42		// All cycle checks in this one request share a single memoized walk over the
43		// graph as it stands now: probe records whether each visited node can reach
44		// dataset.Name through existing parent edges. Candidate upstreams that come
45		// from the same source or merge repeatedly (diamonds) then traverse the
46		// shared lineage once instead of re-walking it per candidate. The recorded
47		// conclusion is a property of the current graph, so it is never reused
48		// across registrations.
49		probe := newAncestorProbe(graph, dataset.Name)
50		for _, parent := range parents {
51			if parent == dataset.Name {
52				return errInvalid("dataset " + dataset.Name + " cannot be its own parent")
53			}
54			if _, ok := graph[parent]; !ok {
55				return errInvalid("unknown parent " + parent)
56			}
57			// A new edge dataset -> parent closes a cycle exactly when parent can
58			// already reach dataset through existing parent edges. This covers
59			// transitive paths of any depth, not only direct mutual references;
60			// shared ancestors and diamond merges read as the benign merges they are
61			// unless a branch genuinely leads back to dataset.
62			if probe.canReach(parent) {
63				return errInvalid("cycle through " + parent + " for dataset " + dataset.Name)
64			}
65			if !known[parent] {
66				known[parent] = true
67				upstreams = append(upstreams, parent)
68			}
69		}
70	
71		entry, existed := graph[dataset.Name]
72		if !existed {
73			entry = &Lineage{Dataset: dataset.Name}
74		}
75	
76		// Remove reverse edges from upstreams the dataset no longer declares.
77		for _, old := range entry.Parents {
78			if known[old] {
79				continue
80			}
81			if p, ok := graph[old]; ok {
82				p.Children = removeChild(p.Children, dataset.Name)
83			}
84		}
85	
86		// Mirror every declared upstream exactly once. An existing edge keeps its
87		// position; a missing edge is appended after the current children.
88		for _, parent := range upstreams {
89			graph[parent].Children = addChildOnce(graph[parent].Children, dataset.Name)
90		}
91	
92		entry.Parents = upstreams
93		if !existed {
94			graph[dataset.Name] = entry
95		}
96		return nil
97	}
98	
99	// ancestorProbe answers "can node reach target by following parent edges?" for
100	// many starting nodes against one fixed, read-only snapshot of the graph, i.e.
101	// whether target is among each node's direct or transitive upstreams. Each node
102	// in the shared ancestry is resolved at most once, so candidate parents that
103	// descend from a common source or merge along the way reuse the same findings
104	// instead of each paying for a complete traversal.
105	type ancestorProbe struct {
106		graph  map[string]*Lineage
107		target string
108		// resolved caches the conclusion for every fully explored node; visiting
109		// marks nodes mid-resolution. Register never accepts cycles, but visiting
110		// doubles as cycle protection regardless.
111		resolved map[string]bool
112		visiting map[string]bool
113	}
114	
115	func newAncestorProbe(graph map[string]*Lineage, target string) *ancestorProbe {
116		return &ancestorProbe{
117			graph:    graph,
118			target:   target,
119			resolved: map[string]bool{},
120			visiting: map[string]bool{},
121		}
122	}
123	
124	func (p *ancestorProbe) canReach(node string) bool {
125		if node == p.target {
126			return true
127		}
128		if hit, ok := p.resolved[node]; ok {
129			return hit
130		}
131		if p.visiting[node] {
132			return false
133		}
134		p.visiting[node] = true
135	
136		found := false
137		if entry, ok := p.graph[node]; ok {
138			for _, parent := range entry.Parents {
139				if p.canReach(parent) {
140					found = true
141					break
142				}
143			}
144		}
145		delete(p.visiting, node)
146		p.resolved[node] = found
147		return found
148	}
149	
150	// removeChild drops every occurrence of child from children, preserving the
151	// relative order of the remaining entries.
152	func removeChild(children []string, child string) []string {
153		out := children[:0]
154		for _, c := range children {
155			if c != child {
156				out = append(out, c)
157			}
158		}
159		return out
160	}
161	
162	// addChildOnce ensures child appears exactly once in children. An existing entry
163	// keeps its position (duplicate later entries are dropped); otherwise child is
164	// appended at the end.
165	func addChildOnce(children []string, child string) []string {
166		out := children[:0]
167		present := false
168		for _, c := range children {
169			if c == child {
170				if present {
171					continue
172				}
173				present = true
174			}
175			out = append(out, c)
176		}
177		if !present {
178			out = append(out, child)
179		}
180		return out
181	}
182	
183	// Impact names one dataset directly or indirectly downstream of an impact
184	// query's origin. Distance is the number of lineage edges on the shortest path
185	// from the origin to this dataset (a direct downstream has distance 1), and
186	// Path is that shortest path written from the origin to the dataset, one name
187	// per hop.
188	type Impact struct {
189		Dataset  string
190		Distance int
191		Path     []string
192	}
193	
194	// Impacts returns every dataset directly or indirectly downstream of origin,
195	// i.e. every dataset reachable from origin by following child edges. The origin
196	// itself is never listed, and datasets with no such connection never appear.
197	//
198	// Distance, the tie-broken explanation path, result ordering, read-only graph
199	// access and error handling all follow the single shared lineage-query rule
200	// set implemented by traceLineage; only the direction is specific to Impacts:
201	// child edges outward, with paths written from the origin. An empty origin is
202	// rejected as a missing name; an origin absent from the graph (including an
203	// empty or nil graph) is rejected with an error naming it and no partial
204	// results.
205	func Impacts(graph map[string]*Lineage, origin string) ([]Impact, error) {
206		hits, err := traceLineage(graph, origin, dirDownstream)
207		if err != nil {
208			return nil, err
209		}
210		impacts := make([]Impact, len(hits))
211		for i, hit := range hits {
212			impacts[i] = Impact{Dataset: hit.name, Distance: hit.distance, Path: hit.path}
213		}
214		return impacts, nil
215	}
216	
217	// Upstream names one dataset directly or indirectly upstream of a provenance
218	// query's target. Distance is the number of lineage edges on the shortest path
219	// from this upstream to the target (a direct upstream has distance 1), and
220	// Path is that shortest path written along the actual derivation direction,
221	// from this upstream to the queried dataset, one name per hop.
222	type Upstream struct {
223		Dataset  string
224		Distance int
225		Path     []string
226	}
227	
228	// Upstreams returns every dataset directly or indirectly upstream of target,
229	// i.e. every dataset reachable from target by following parent edges. The
230	// target itself is never listed, its downstreams never appear, and datasets
231	// with no such connection never appear.
232	//
233	// Distance, the tie-broken explanation path, result ordering, read-only graph
234	// access and error handling all follow the single shared lineage-query rule
235	// set implemented by traceLineage; only the direction is specific to
236	// Upstreams: parent edges inward, with paths written from each source toward
237	// the target. An empty target is rejected as a missing name; a target absent
238	// from the graph (including an empty or nil graph) is rejected with an error
239	// naming it and no partial results.
240	func Upstreams(graph map[string]*Lineage, target string) ([]Upstream, error) {
241		hits, err := traceLineage(graph, target, dirUpstream)
242		if err != nil {
243			return nil, err
244		}
245		upstreams := make([]Upstream, len(hits))
246		for i, hit := range hits {
247			upstreams[i] = Upstream{Dataset: hit.name, Distance: hit.distance, Path: hit.path}
248		}
249		return upstreams, nil
250	}
251	
252	// queryDirection carries the only way the two lineage queries differ: which
253	// edges to walk and from which end an explanation path is written.
254	type queryDirection int
255	
256	const (
257		// dirDownstream follows child edges away from the query's origin and grows
258		// explanation paths at the far end (origin -> ... -> dataset).
259		dirDownstream queryDirection = iota
260		// dirUpstream follows parent edges away from the query's target and grows
261		// explanation paths at the near end (source -> ... -> target).
262		dirUpstream
263	)
264	
265	// neighbors lists the datasets one edge beyond node in the query direction.
266	func (d queryDirection) neighbors(node *Lineage) []string {
267		if d == dirDownstream {
268			return node.Children
269		}
270		return node.Parents
271	}
272	
273	// extendPath grows a committed shortest path by one hop, placing the new hop
274	// where the explanation direction requires: a downstream hop is appended
275	// (origin -> node -> hop), an upstream hop is prepended (hop -> node ->
276	// target). The result always gets a fresh backing array, so candidates never
277	// alias each other, committed paths, or slices stored in the graph.
278	func (d queryDirection) extendPath(path []string, hop string) []string {
279		extended := make([]string, len(path)+1)
280		if d == dirDownstream {
281			copy(extended, path)
282			extended[len(extended)-1] = hop
283			return extended
284		}
285		extended[0] = hop
286		copy(extended[1:], path)
287		return extended
288	}
289	
290	// lineageHit is one direction-neutral query result: a reached dataset besides
291	// the query's own node, its shortest edge distance, and the lexicographically
292	// smallest shortest explanation path held in an independent slice.
293	type lineageHit struct {
294		name     string
295		distance int
296		path     []string
297	}
298	
299	// traceLineage runs the one query rule set shared by Impacts and Upstreams and
300	// returns every dataset reachable from start besides start itself.
301	//
302	// The traversal is a BFS that commits a whole distance level at once, so a node
303	// reached through several branches within the same level keeps exactly one
304	// candidate before the level commits. The rules shared by both directions are:
305	//
306	//   - Distance is the minimum number of lineage edges; a node committed on an
307	//     earlier level can never be re-explained at a longer one (Register
308	//     rejects cycles, so equal-length rediscoveries only happen inside one
309	//     level's candidate map).
310	//   - Each dataset appears at most once, however many branches merge into it.
311	//   - Among equal-length shortest paths, the lexicographically smallest full
312	//     path wins: names are compared one by one from the path's beginning in Go
313	//     string order. Downstream paths begin at the query origin and upstream
314	//     paths at the source, so candidates for one upstream share their first
315	//     hop and compare directly against the committed tails.
316	//   - Hits are ordered by distance ascending and then by dataset name, never
317	//     by registration order or the stored parent/child list order.
318	//
319	// Explanation paths are written in the query direction (see extendPath). The
320	// graph is read only and every returned path is an independent copy. An empty
321	// start is rejected as a missing name; an unregistered start (also against an
322	// empty or nil graph) is rejected with an error naming it, with nil results;
323	// a registered start that reaches nothing returns a non-nil empty slice.
324	func traceLineage(graph map[string]*Lineage, start string, direction queryDirection) ([]lineageHit, error) {
325		if start == "" {
326			return nil, errInvalid("dataset name is required")
327		}
328		if _, ok := graph[start]; !ok {
329			return nil, errInvalid("dataset not found: " + start)
330		}
331	
332		distance := map[string]int{start: 0}
333		best := map[string][]string{start: {start}}
334		frontier := []string{start}
335		for level := 0; len(frontier) > 0; level++ {
336			nextDistance := level + 1
337			candidates := map[string][]string{}
338			var next []string
339			for _, node := range frontier {
340				for _, hop := range direction.neighbors(graph[node]) {
341					if _, seen := distance[hop]; seen {
342						continue // reached on an earlier, strictly shorter level
343					}
344					candidate := direction.extendPath(best[node], hop)
345					if current, ok := candidates[hop]; !ok || lessPath(candidate, current) {
346						if !ok {
347							next = append(next, hop)
348						}
349						candidates[hop] = candidate
350					}
351				}
352			}
353			for _, hop := range next {
354				distance[hop] = nextDistance
355				best[hop] = candidates[hop]
356			}
357			frontier = next
358		}
359	
360		hits := make([]lineageHit, 0, len(distance)-1)
361		for name, d := range distance {
362			if name == start {
363				continue
364			}
365			hits = append(hits, lineageHit{
366				name:     name,
367				distance: d,
368				path:     append([]string(nil), best[name]...),
369			})
370		}
371		sort.Slice(hits, func(i, j int) bool {
372			if hits[i].distance != hits[j].distance {
373				return hits[i].distance < hits[j].distance
374			}
375			return hits[i].name < hits[j].name
376		})
377		return hits, nil
378	}
379	
380	// lessPath reports whether path a sorts before path b as a name sequence:
381	// names are compared with Go string order from the start, and an equal prefix
382	// makes the shorter path smaller.
383	func lessPath(a, b []string) bool {
384		for i := 0; i < len(a) && i < len(b); i++ {
385			if a[i] != b[i] {
386				return a[i] < b[i]
387			}
388		}
389		return len(a) < len(b)
390	}
391	
392	// Roots lists datasets with no parents, in stable order.
393	func Roots(graph map[string]*Lineage) []string {
394		var roots []string
395		for name, entry := range graph {
396			if len(entry.Parents) == 0 {
397				roots = append(roots, name)
398			}
399		}
400		sort.Strings(roots)
401		return roots
402	}
403	
404	type errInvalid string
405	
406	func (e errInvalid) Error() string { return string(e) }
407

