502	func assertImpact(t *testing.T, impacts []Impact, name string, wantDistance int, wantPath []string) {
503		t.Helper()
504		for _, im := range impacts {
505			if im.Dataset != name {
506				continue
507			}
508			if im.Distance != wantDistance {
509				t.Errorf("impact %s distance = %d, want %d", name, im.Distance, wantDistance)
