804	// Re-wiring report from [a b] to [b] removes the short raw -> a -> report
805	// path, but the longer raw -> a -> b -> report path still connects everything.
806	// Distances and explanation paths must be recomputed under the current edges,
807	// not inherited from before the re-wire.
808	func TestImpactsAfterRewireLongerPathSurvives(t *testing.T) {
809		graph := map[string]*Lineage{}
810		mustRegister(t, graph, "raw")
811		mustRegister(t, graph, "a", "raw")
812		mustRegister(t, graph, "b", "a")
813		mustRegister(t, graph, "report", "a", "b")
814		mustRegister(t, graph, "view", "report")
815	
816		before := mustImpacts(t, graph, "raw")
817		assertImpact(t, before, "report", 2, []string{"raw", "a", "report"})
818		assertImpact(t, before, "view", 3, []string{"raw", "a", "report", "view"})
819	
820		// Drop the direct a -> report edge; only the route through b remains.
821		mustRegister(t, graph, "report", "b")
822		assertConsistent(t, graph)
823	
824		impacts := mustImpacts(t, graph, "raw")
825		if got, want := impactNames(impacts), []string{"a", "b", "report", "view"}; !reflect.DeepEqual(got, want) {
826			t.Fatalf("impact order = %v, want %v", got, want)
827		}
828		assertImpactOnce(t, impacts, "report", 3, []string{"raw", "a", "b", "report"})
829		assertImpactOnce(t, impacts, "view", 4, []string{"raw", "a", "b", "report", "view"})
830	
831		// From the dropped upstream a, report was distance 1 before; now only the
832		// longer current path may be reported.
833		fromOld := mustImpacts(t, graph, "a")
834		if got, want := impactNames(fromOld), []string{"b", "report", "view"}; !reflect.DeepEqual(got, want) {
835			t.Fatalf("impacts from old upstream = %v, want %v", got, want)
836		}
837		assertImpactOnce(t, fromOld, "report", 2, []string{"a", "b", "report"})
838		assertImpactOnce(t, fromOld, "view", 3, []string{"a", "b", "report", "view"})
