841	// When the re-wire severs the last lineage path from the old source, the
842	// re-wired dataset and the downstreams reachable only through it leave the old
843	// source's scope together, while the old source's other branches still return.
844	// The new source sees the moved subtree with paths rooted at itself.
845	func TestImpactsAfterRewireLastPathRemoved(t *testing.T) {
846		graph := map[string]*Lineage{}
847		mustRegister(t, graph, "raw")
