849		mustRegister(t, graph, "leaf", "mid")
850		mustRegister(t, graph, "side", "raw")
851		mustRegister(t, graph, "sideleaf", "side")
852		mustRegister(t, graph, "newsrc")
853	
854		// mid moves from raw to newsrc, keeping its own downstream leaf.
855		mustRegister(t, graph, "mid", "newsrc")
856		assertConsistent(t, graph)
857	
858		fromOld := mustImpacts(t, graph, "raw")
859		if got, want := impactNames(fromOld), []string{"side", "sideleaf"}; !reflect.DeepEqual(got, want) {
860			t.Fatalf("impacts from old source = %v, want %v (mid and leaf must be gone)", got, want)
861		}
862		assertImpact(t, fromOld, "side", 1, []string{"raw", "side"})
863		assertImpact(t, fromOld, "sideleaf", 2, []string{"raw", "side", "sideleaf"})
864	
865		fromNew := mustImpacts(t, graph, "newsrc")
866		if got, want := impactNames(fromNew), []string{"mid", "leaf"}; !reflect.DeepEqual(got, want) {
867			t.Fatalf("impacts from new source = %v, want %v", got, want)
868		}
869		assertImpactOnce(t, fromNew, "mid", 1, []string{"newsrc", "mid"})
870		assertImpactOnce(t, fromNew, "leaf", 2, []string{"newsrc", "mid", "leaf"})
871	
872		// The moved subtree is still intact when queried from itself.
873		fromMid := mustImpacts(t, graph, "mid")
874		assertImpact(t, fromMid, "leaf", 1, []string{"mid", "leaf"})
875	
876		// Cutting mid loose entirely (no upstreams) empties the new source's scope:
877		// the source remains a valid origin and answers with an empty list.
878		mustRegister(t, graph, "mid")
879		assertConsistent(t, graph)
880		impacts, err := Impacts(graph, "newsrc")
881		if err != nil {
882			t.Fatalf("Impacts(newsrc) with no remaining downstream: %v", err)
883		}
884		if impacts == nil || len(impacts) != 0 {
885			t.Fatalf("want empty non-nil list from newsrc, got %v", impacts)
886		}
887		if got, want := impactNames(mustImpacts(t, graph, "raw")), []string{"side", "sideleaf"}; !reflect.DeepEqual(got, want) {
888			t.Fatalf("old source other branches = %v, want %v", got, want)
889		}
