952	// After a re-wire leaves two equal-length shortest paths, the lexicographically
953	// smallest full name sequence wins regardless of the stored parent list order,
954	// and neither registration order nor upstream list order affects the result.
955	func TestImpactsRewireTieBreakAndOrderInvariance(t *testing.T) {
956		build := func(parents ...string) map[string]*Lineage {
957			graph := map[string]*Lineage{}
958			mustRegister(t, graph, "o")
959			mustRegister(t, graph, "x2", "o") // larger name registered first on purpose
960			mustRegister(t, graph, "x1", "o")
961			mustRegister(t, graph, "d", parents...)
962			mustRegister(t, graph, "e", "d")
963			return graph
964		}
965	
966		// d ends up with parents [x2 x1] (list order disagreeing with name order)
967		// either by direct registration or by re-wiring from a single parent.
968		direct := build("x2", "x1")
969		rewired := build("x1")
970		mustRegister(t, rewired, "d", "x2", "x1")
971		assertConsistent(t, rewired)
972	
973		want := mustImpacts(t, direct, "o")
974		assertImpactOnce(t, want, "d", 2, []string{"o", "x1", "d"})
975		assertImpactOnce(t, want, "e", 3, []string{"o", "x1", "d", "e"})
976		if got, wantNames := impactNames(want), []string{"x1", "x2", "d", "e"}; !reflect.DeepEqual(got, wantNames) {
977			t.Fatalf("impact order = %v, want %v", got, wantNames)
978		}
979	
980		if got := mustImpacts(t, rewired, "o"); !reflect.DeepEqual(got, want) {
981			t.Fatalf("re-wired graph impacts = %v, want %v (registration history must not matter)", got, want)
982		}
983	
984		// Same final graph, but children registered in the opposite order and the
985		// upstream list flipped: the query result must be identical.
986		flipped := map[string]*Lineage{}
987		mustRegister(t, flipped, "o")
988		mustRegister(t, flipped, "x1", "o")
989		mustRegister(t, flipped, "x2", "o")
990		mustRegister(t, flipped, "d", "x1", "x2")
991		mustRegister(t, flipped, "e", "d")
992		if got := mustImpacts(t, flipped, "o"); !reflect.DeepEqual(got, want) {
993			t.Fatalf("flipped build impacts = %v, want %v (registration and list order must not matter)", got, want)
994		}
