1008	// Regression for a multi-path merge where comparing the full explanation path
1009	// and comparing only the merge node's direct upstream name give different
1010	// answers. source feeds a and b; a feeds z; b feeds c; report depends on z and
1011	// c together (c declared ahead of z on purpose); view depends on report. From
1012	// source both source->a->z->report and source->b->c->report have length 3. A
1013	// rule that only compares the final upstream would wrongly prefer the c route
1014	// (c < z); the full-path rule must compare from the origin and pick the a
1015	// route, because the paths first differ at hop 1 where a < b. view inherits
1016	// that explanation one hop further on.
1017	func TestImpactsMergedBranchesFullPathTieBreak(t *testing.T) {
1018		// Each sequence builds the same graph with a legal but different
1019		// registration order; the second also flips report's upstream list, and the
1020		// third registers the isolated node early. Names, distances and paths must
1021		// come out identical regardless.
1022		sequences := [][][]string{
1023			{
1024				{"source"},
1025				{"b", "source"}, // b-side branch registered first
1026				{"a", "source"},
1027				{"c", "b"},
1028				{"z", "a"},
1029				{"report", "c", "z"}, // c listed ahead of z on purpose
1030				{"view", "report"},
1031				{"isolated"},
1032			},
1033			{
1034				{"source"},
1035				{"a", "source"}, // opposite branch registered first
1036				{"z", "a"},
1037				{"b", "source"},
1038				{"c", "b"},
1039				{"report", "z", "c"}, // direct-upstream order flipped
1040				{"view", "report"},
1041				{"isolated"},
1042			},
1043			{
1044				{"source"},
1045				{"isolated"},
1046				{"b", "source"},
1047				{"a", "source"},
1048				{"z", "a"},
1049				{"c", "b"},
1050				{"report", "c", "z"},
1051				{"view", "report"},
1052			},
1053		}
1054	
1055		want := []Impact{
1056			{Dataset: "a", Distance: 1, Path: []string{"source", "a"}},
1057			{Dataset: "b", Distance: 1, Path: []string{"source", "b"}},
1058			{Dataset: "c", Distance: 2, Path: []string{"source", "b", "c"}},
1059			{Dataset: "z", Distance: 2, Path: []string{"source", "a", "z"}},
1060			{Dataset: "report", Distance: 3, Path: []string{"source", "a", "z", "report"}},
1061			{Dataset: "view", Distance: 4, Path: []string{"source", "a", "z", "report", "view"}},
1062		}
1063	
1064		for i, seq := range sequences {
1065			graph := buildRegisteredGraph(t, seq)
1066			assertConsistent(t, graph)
1067			before := snapshot(graph)
1068	
1069			impacts := mustImpacts(t, graph, "source")
1070			if !reflect.DeepEqual(impacts, want) {
1071				t.Fatalf("sequence %d: impacts = %v, want %v", i, impacts, want)
1072			}
1073	
1074			// Anchors with explicit messages: the merge node is explained exactly
1075			// once through a/z even though c sorts ahead of z, and view continues
1076			// along that same route.
1077			assertImpactOnce(t, impacts, "report", 3, []string{"source", "a", "z", "report"})
1078			assertImpactOnce(t, impacts, "view", 4, []string{"source", "a", "z", "report", "view"})
1079	
1080			// The origin itself and an unconnected dataset never appear.
1081			if names := impactNames(impacts); slices.Contains(names, "source") || slices.Contains(names, "isolated") {
1082				t.Fatalf("sequence %d: origin or isolated dataset leaked into %v", i, names)
1083			}
1084	
1085			// The query changes no node, relationship or stored list order.
1086			if !reflect.DeepEqual(snapshot(graph), before) {
1087				t.Fatalf("sequence %d: query changed graph: before=%v after=%v", i, before, snapshot(graph))
1088			}
1089		}
1090	}
