1441		if err == nil || !strings.Contains(err.Error(), "ghost") || upstreams != nil {
1442			t.Fatalf("empty graph: want naming error and nil results, got %v, %v", upstreams, err)
1443		}
1444		upstreams, err = Upstreams(nil, "ghost")
1445		if err == nil || !strings.Contains(err.Error(), "ghost") || upstreams != nil {
1446			t.Fatalf("nil graph: want naming error and nil results, got %v, %v", upstreams, err)
1447		}
1448	}
1449	
1450	// Names match by exact registered value.
1451	func TestUpstreamsExactNameMatch(t *testing.T) {
1452		graph := map[string]*Lineage{}
1453		mustRegister(t, graph, "raw")
1454		mustRegister(t, graph, "RAW", "raw")
1455	
1456		if _, err := Upstreams(graph, "RaW"); err == nil || !strings.Contains(err.Error(), "RaW") {
1457			t.Fatalf("case-insensitive match: want error naming RaW, got %v", err)
1458		}
1459		upstreams, err := Upstreams(graph, "RAW")
1460		if err != nil {
1461			t.Fatalf("Upstreams(RAW): %v", err)
1462		}
1463		assertUpstream(t, upstreams, "raw", 1, []string{"raw", "RAW"})
1464	}
