1466	// A query never mutates the graph, and mutating the returned list or paths
1467	// cannot reach back into the graph, into other records, or into later queries.
1468	func TestUpstreamsReadOnlyAndIsolated(t *testing.T) {
1469		graph := map[string]*Lineage{}
1470		mustRegister(t, graph, "raw")
1471		mustRegister(t, graph, "a", "raw")
1472		mustRegister(t, graph, "b", "raw")
1473		mustRegister(t, graph, "report", "a", "b")
1474		before := snapshot(graph)
1475	
1476		upstreams, err := Upstreams(graph, "report")
1477		if err != nil {
1478			t.Fatalf("Upstreams(report): %v", err)
1479		}
1480		if !reflect.DeepEqual(snapshot(graph), before) {
1481			t.Fatalf("query changed graph: before=%v after=%v", before, snapshot(graph))
1482		}
1483	
1484		// Abuse the returned slices, then confirm the graph and a repeated query
1485		// are both untouched.
1486		upstreams[0].Path[0] = "tampered"
1487		upstreams[0].Path = append(upstreams[0].Path, "extra")
1488		upstreams[0].Dataset = "tampered"
1489		upstreams[0].Distance = 99
1490		if !reflect.DeepEqual(snapshot(graph), before) {
1491			t.Fatalf("mutating results changed graph: before=%v after=%v", before, snapshot(graph))
1492		}
1493		fresh := mustUpstreams(t, graph, "report")
1494		assertUpstream(t, fresh, "raw", 2, []string{"raw", "a", "report"})
1495	
1496		// A failed query is also read-only.
1497		if _, err := Upstreams(graph, "missing"); err == nil {
1498			t.Fatal("expected not-found error")
1499		}
1500		if !reflect.DeepEqual(snapshot(graph), before) {
1501			t.Fatalf("failed query changed graph: before=%v after=%v", before, snapshot(graph))
1502		}
1503		assertConsistent(t, graph)
1504	}
