1506	// After report's direct upstreams are replaced by a same-name Register, a new
1507	// query reflects the current edges, while the previously returned result keeps
1508	// its original content.
1509	func TestUpstreamsReflectReregisterAndOldResultStable(t *testing.T) {
1510		graph := map[string]*Lineage{}
1511		mustRegister(t, graph, "raw")
1512		mustRegister(t, graph, "a", "raw")
1513		mustRegister(t, graph, "b", "raw")
1514		mustRegister(t, graph, "report", "a", "b")
1515	
1516		before, err := Upstreams(graph, "report")
1517		if err != nil {
1518			t.Fatalf("Upstreams(report): %v", err)
1519		}
1520		assertUpstreamOnce(t, before, "raw", 2, []string{"raw", "a", "report"})
1521		beforeCopy := make([]Upstream, len(before))
1522		for i, up := range before {
1523			beforeCopy[i] = Upstream{up.Dataset, up.Distance, append([]string(nil), up.Path...)}
1524		}
1525	
1526		// report now depends on b only: a leaves its upstream set entirely, raw
1527		// remains reachable through b at distance 2 via the surviving route.
1528		mustRegister(t, graph, "report", "b")
1529	
1530		after, err := Upstreams(graph, "report")
1531		if err != nil {
1532			t.Fatalf("Upstreams(report) after re-register: %v", err)
1533		}
1534		if got, want := upstreamNames(after), []string{"b", "raw"}; !reflect.DeepEqual(got, want) {
1535			t.Fatalf("upstream order = %v, want %v", got, want)
1536		}
1537		assertUpstreamOnce(t, after, "b", 1, []string{"b", "report"})
1538		assertUpstreamOnce(t, after, "raw", 2, []string{"raw", "b", "report"})
1539	
1540		if !reflect.DeepEqual(before, beforeCopy) {
1541			t.Fatalf("earlier result changed after re-register/new query: before=%v snapshot=%v", before, beforeCopy)
1542		}
1543	}
1544	
1545	// Regression for replacing a middle dataset's direct upstreams so that the
1546	// shortest route from a source to the report is deleted while a longer route
1547	// keeps the source involved. raw feeds a and b; a feeds z; b feeds c; middle
1548	// depends on raw, z and c together; report depends on middle. Initially raw
1549	// reaches report at distance 2 via raw -> middle -> report. Re-registering
1550	// middle with only z and c deletes that direct edge, but raw still derives
1551	// report through raw -> a -> z -> middle -> report and raw -> b -> c -> middle
1552	// -> report, both of length 4: raw must stay listed exactly once, at distance
1553	// 4, and must not keep the stale distance-2 explanation. The two surviving
1554	// routes have equal length, so the full path is compared name by name from the
1555	// source: the paths first differ at hop 1 where a < b, hence the a/z route
1556	// wins even though middle's direct upstream c sorts ahead of z. report's own
1557	// direct dependency is untouched, so it still resolves every source through
1558	// middle.
1559	func TestUpstreamsAfterRewireLongerRouteSurvives(t *testing.T) {
1560		// Two builds of the same lineage with the independent branches registered
1561		// in opposite orders and middle's upstream list written differently; the
1562		// rewire likewise lists z and c in opposite orders. Identical final
1563		// relationships must give identical results.
1564		builds := []struct {
1565			registrations [][]string
1566			newParents    []string
1567		}{
1568			{
1569				registrations: [][]string{
1570					{"raw"},
1571					{"a", "raw"},
1572					{"z", "a"},
1573					{"b", "raw"},
1574					{"c", "b"},
1575					{"middle", "raw", "z", "c"},
1576					{"report", "middle"},
1577				},
1578				newParents: []string{"z", "c"},
1579			},
1580			{
1581				registrations: [][]string{
1582					{"raw"},
1583					{"b", "raw"}, // b-side branch registered first
1584					{"c", "b"},
1585					{"a", "raw"},
1586					{"z", "a"},
1587					{"middle", "c", "z", "raw"}, // upstream list order flipped
1588					{"report", "middle"},
1589				},
1590				newParents: []string{"c", "z"},
1591			},
1592		}
1593	
1594		wantBefore := []Upstream{
1595			{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
1596			{Dataset: "c", Distance: 2, Path: []string{"c", "middle", "report"}},
1597			{Dataset: "raw", Distance: 2, Path: []string{"raw", "middle", "report"}},
1598			{Dataset: "z", Distance: 2, Path: []string{"z", "middle", "report"}},
1599			{Dataset: "a", Distance: 3, Path: []string{"a", "z", "middle", "report"}},
1600			{Dataset: "b", Distance: 3, Path: []string{"b", "c", "middle", "report"}},
1601		}
1602		wantAfter := []Upstream{
1603			{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
1604			{Dataset: "c", Distance: 2, Path: []string{"c", "middle", "report"}},
1605			{Dataset: "z", Distance: 2, Path: []string{"z", "middle", "report"}},
1606			{Dataset: "a", Distance: 3, Path: []string{"a", "z", "middle", "report"}},
1607			{Dataset: "b", Distance: 3, Path: []string{"b", "c", "middle", "report"}},
1608			{Dataset: "raw", Distance: 4, Path: []string{"raw", "a", "z", "middle", "report"}},
1609		}
1610	
1611		for i, build := range builds {
1612			graph := buildRegisteredGraph(t, build.registrations)
1613			assertConsistent(t, graph)
1614	
1615			before := mustUpstreams(t, graph, "report")
1616			if !reflect.DeepEqual(before, wantBefore) {
1617				t.Fatalf("build %d: upstreams before rewire = %v, want %v", i, before, wantBefore)
1618			}
1619			// Anchor: the direct raw -> middle edge makes raw a distance-2 source.
1620			assertUpstreamOnce(t, before, "raw", 2, []string{"raw", "middle", "report"})
1621			beforeCopy := make([]Upstream, len(before))
1622			for j, up := range before {
1623				beforeCopy[j] = Upstream{up.Dataset, up.Distance, append([]string(nil), up.Path...)}
1624			}
1625	
1626			// Replace middle's direct upstreams, dropping the raw -> middle edge.
1627			// report's own direct dependency is not part of the request.
1628			mustRegister(t, graph, "middle", build.newParents...)
1629			assertConsistent(t, graph)
1630			assertEntry(t, graph, "middle", build.newParents, []string{"report"})
1631			assertEntry(t, graph, "report", []string{"middle"}, nil)
1632			graphBeforeQuery := snapshot(graph)
1633	
1634			after := mustUpstreams(t, graph, "report")
1635			if !reflect.DeepEqual(after, wantAfter) {
1636				t.Fatalf("build %d: upstreams after rewire = %v, want %v", i, after, wantAfter)
1637			}
1638			// Anchors with explicit messages: raw survives exactly once at the
1639			// longer distance, explained from the source hop by hop (a < b decides
1640			// at hop 1; middle's direct upstreams c < z must not decide it), and
1641			// the stale distance-2 route is gone.
1642			assertUpstreamOnce(t, after, "raw", 4, []string{"raw", "a", "z", "middle", "report"})
1643			assertUpstreamOnce(t, after, "middle", 1, []string{"middle", "report"})
1644	
1645			// The target never lists itself.
1646			if names := upstreamNames(after); slices.Contains(names, "report") {
1647				t.Fatalf("build %d: target leaked into its own upstreams %v", i, names)
1648			}
1649	
1650			// The query changed no node, relationship or stored list order.
1651			if !reflect.DeepEqual(snapshot(graph), graphBeforeQuery) {
1652				t.Fatalf("build %d: query changed graph: before=%v after=%v", i, graphBeforeQuery, snapshot(graph))
1653			}
1654	
1655			// The result obtained before the rewire kept its original content.
1656			if !reflect.DeepEqual(before, beforeCopy) {
1657				t.Fatalf("build %d: earlier result changed after re-register/new query: before=%v snapshot=%v",
1658					i, before, beforeCopy)
1659			}
1660		}
1661	}
1662	
1663	// Regression for detaching a middle dataset from ALL of its direct upstreams
1664	// by re-registering it with an empty upstream list, where the report still has
1665	// a second branch reaching back to the old source. raw derives a and z; middle
1666	// depends on raw and a; report depends on middle and z. Before the detach, raw
1667	// reaches report over two shortest routes of length 2 (raw -> middle -> report
1668	// and raw -> z -> report), and the lexicographically smaller middle route is
1669	// the explanation. Detaching middle makes it a new root without deleting it or
1670	// breaking its downstream edge to report: middle stays a distance-1 source, a
1671	// leaves report's sources entirely, but raw survives exactly once at distance
1672	// 2 through the remaining z branch, with the explanation re-derived as
1673	// raw -> z -> report instead of the removed middle route.
1674	func TestUpstreamsAfterDetachAllUpstreamsSecondBranchSurvives(t *testing.T) {
1675		graph := buildRegisteredGraph(t, [][]string{
1676			{"raw"},
1677			{"a", "raw"},
1678			{"z", "raw"},
1679			{"middle", "raw", "a"},
1680			{"report", "middle", "z"},
1681		})
1682		assertConsistent(t, graph)
1683	
1684		wantBefore := []Upstream{
1685			{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
1686			{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
1687			{Dataset: "a", Distance: 2, Path: []string{"a", "middle", "report"}},
1688			{Dataset: "raw", Distance: 2, Path: []string{"raw", "middle", "report"}},
1689		}
1690		before := mustUpstreams(t, graph, "report")
1691		if !reflect.DeepEqual(before, wantBefore) {
1692			t.Fatalf("upstreams before detach = %v, want %v", before, wantBefore)
1693		}
1694		// Anchor: of the two length-2 routes from raw, the middle route explains.
1695		assertUpstreamOnce(t, before, "raw", 2, []string{"raw", "middle", "report"})
1696		beforeCopy := make([]Upstream, len(before))
1697		for i, up := range before {
1698			beforeCopy[i] = Upstream{up.Dataset, up.Distance, append([]string(nil), up.Path...)}
1699		}
1700	
1701		// Detach middle from every direct upstream. report's own direct
1702		// dependencies are not part of the request and must not change.
1703		mustRegister(t, graph, "middle")
1704		assertConsistent(t, graph)
1705		assertEntry(t, graph, "middle", nil, []string{"report"})
1706		assertEntry(t, graph, "report", []string{"middle", "z"}, nil)
1707		assertEntry(t, graph, "raw", nil, []string{"a", "z"})
1708		assertEntry(t, graph, "a", []string{"raw"}, nil)
1709		assertEntry(t, graph, "z", []string{"raw"}, []string{"report"})
1710		graphBeforeQuery := snapshot(graph)
1711	
1712		wantAfter := []Upstream{
1713			{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
1714			{Dataset: "z", Distance: 1, Path: []string{"z", "report"}},
1715			{Dataset: "raw", Distance: 2, Path: []string{"raw", "z", "report"}},
1716		}
1717		after := mustUpstreams(t, graph, "report")
1718		if !reflect.DeepEqual(after, wantAfter) {
1719			t.Fatalf("upstreams after detach = %v, want %v", after, wantAfter)
1720		}
1721		// Anchors with explicit messages: middle stays a direct source, a is gone,
1722		// and raw survives exactly once via z — it must not follow a out of the
1723		// result, nor keep the detached raw -> middle -> report explanation.
1724		assertUpstreamOnce(t, after, "middle", 1, []string{"middle", "report"})
1725		assertUpstreamOnce(t, after, "raw", 2, []string{"raw", "z", "report"})
1726		if names := upstreamNames(after); slices.Contains(names, "a") || slices.Contains(names, "report") {
1727			t.Fatalf("detached upstream or target leaked into %v", names)
1728		}
1729	
1730		// The query is read-only and does not resurrect middle's detached
1731		// upstreams.
1732		if !reflect.DeepEqual(snapshot(graph), graphBeforeQuery) {
1733			t.Fatalf("query changed graph: before=%v after=%v", graphBeforeQuery, snapshot(graph))
1734		}
1735		assertEntry(t, graph, "middle", nil, []string{"report"})
1736	
1737		// The result obtained before the detach kept its original content.
1738		if !reflect.DeepEqual(before, beforeCopy) {
1739			t.Fatalf("earlier result changed after detach/new query: before=%v snapshot=%v", before, beforeCopy)
1740		}
1741	}
1742	
1743	// Regression for detaching a middle dataset from ALL of its direct upstreams
1744	// where the report has no second branch back to the old sources. raw derives
1745	// a; middle depends on raw and a; report depends on middle alone. After the
1746	// detach, report's only remaining source is middle at distance 1: raw and a
1747	// stay registered in the graph but leave report's upstream list. Querying the
1748	// detached middle itself succeeds with a non-nil empty list — it is a root,
1749	// not a missing dataset, and never lists itself.
1750	func TestUpstreamsAfterDetachAllUpstreamsNoOtherBranch(t *testing.T) {
1751		graph := buildRegisteredGraph(t, [][]string{
1752			{"raw"},
1753			{"a", "raw"},
1754			{"middle", "raw", "a"},
1755			{"report", "middle"},
1756		})
1757		assertConsistent(t, graph)
1758	
1759		wantBefore := []Upstream{
1760			{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
1761			{Dataset: "a", Distance: 2, Path: []string{"a", "middle", "report"}},
1762			{Dataset: "raw", Distance: 2, Path: []string{"raw", "middle", "report"}},
1763		}
1764		before := mustUpstreams(t, graph, "report")
1765		if !reflect.DeepEqual(before, wantBefore) {
1766			t.Fatalf("upstreams before detach = %v, want %v", before, wantBefore)
1767		}
1768	
1769		// Detach middle from every direct upstream; report keeps depending on it.
1770		mustRegister(t, graph, "middle")
1771		assertConsistent(t, graph)
1772		assertEntry(t, graph, "middle", nil, []string{"report"})
1773		assertEntry(t, graph, "report", []string{"middle"}, nil)
1774		assertEntry(t, graph, "raw", nil, []string{"a"})
1775		assertEntry(t, graph, "a", []string{"raw"}, nil)
1776		graphBeforeQuery := snapshot(graph)
1777	
1778		// report's sources shrink to middle alone: raw and a are still registered
1779		// but no longer connected to report.
1780		wantAfter := []Upstream{
1781			{Dataset: "middle", Distance: 1, Path: []string{"middle", "report"}},
1782		}
1783		after := mustUpstreams(t, graph, "report")
1784		if !reflect.DeepEqual(after, wantAfter) {
1785			t.Fatalf("upstreams after detach = %v, want %v", after, wantAfter)
1786		}
1787		assertUpstreamOnce(t, after, "middle", 1, []string{"middle", "report"})
1788		if names := upstreamNames(after); slices.Contains(names, "raw") || slices.Contains(names, "a") {
1789			t.Fatalf("detached sources leaked into %v", names)
1790		}
1791		if _, ok := graph["raw"]; !ok {
1792			t.Fatal("raw must stay registered after the detach")
1793		}
1794		if _, ok := graph["a"]; !ok {
1795			t.Fatal("a must stay registered after the detach")
1796		}
1797	
1798		// The detached middle is a valid query target: a successful non-nil empty
1799		// list, no not-found error, and it never lists itself.
1800		middleUpstreams, err := Upstreams(graph, "middle")
1801		if err != nil {
1802			t.Fatalf("Upstreams(middle) after detach: %v", err)
1803		}
1804		if middleUpstreams == nil || len(middleUpstreams) != 0 {
1805			t.Fatalf("want empty non-nil list from detached middle, got %v", middleUpstreams)
1806		}
1807	
1808		// The queries changed no node, relationship or stored list order, and did
1809		// not resurrect middle's detached upstreams.
1810		if !reflect.DeepEqual(snapshot(graph), graphBeforeQuery) {
1811			t.Fatalf("queries changed graph: before=%v after=%v", graphBeforeQuery, snapshot(graph))
1812		}
1813		assertEntry(t, graph, "middle", nil, []string{"report"})
1814	}
1815	
1816	// A rewire of middle whose new upstream list contains report would close the
1817	// cycle middle -> report -> middle, so the registration must be refused with
1818	// an error naming report. The refusal is atomic: afterwards Upstreams(report)
1819	// returns exactly the sources, distances and explanation paths it returned
1820	// before the attempt, with no trace of the partially requested replacement.
1821	func TestUpstreamsRejectedCycleRewireLeavesResultsUntouched(t *testing.T) {
1822		graph := buildRegisteredGraph(t, [][]string{
1823			{"raw"},
1824			{"a", "raw"},
1825			{"z", "a"},
1826			{"b", "raw"},
1827			{"c", "b"},
1828			{"middle", "raw", "z", "c"},
1829			{"report", "middle"},
1830		})
1831		assertConsistent(t, graph)
1832	
1833		before := mustUpstreams(t, graph, "report")
1834		assertUpstreamOnce(t, before, "raw", 2, []string{"raw", "middle", "report"})
1835		graphBefore := snapshot(graph)
1836	
1837		// report is middle's own downstream: adding it as an upstream closes a
1838		// cycle, and the error must say so naming report.
1839		err := Register(graph, Dataset{Name: "middle"}, []string{"z", "c", "report"})
1840		if err == nil || !strings.Contains(err.Error(), "cycle") || !strings.Contains(err.Error(), "report") {
1841			t.Fatalf("want cycle error naming report, got %v", err)
1842		}
1843	
1844		if !reflect.DeepEqual(snapshot(graph), graphBefore) {
1845			t.Fatalf("rejected rewire changed graph: before=%v after=%v", graphBefore, snapshot(graph))
1846		}
1847		assertEntry(t, graph, "middle", []string{"raw", "z", "c"}, []string{"report"})
1848		assertEntry(t, graph, "report", []string{"middle"}, nil)
1849		assertConsistent(t, graph)
1850	
1851		// The query after the rejected attempt sees exactly the pre-request
1852		// lineage: same sources, distances and explanation paths, nothing partial.
1853		after := mustUpstreams(t, graph, "report")
1854		if !reflect.DeepEqual(after, before) {
1855			t.Fatalf("upstreams after rejected rewire = %v, want %v", after, before)
1856		}
1857		assertUpstreamOnce(t, after, "raw", 2, []string{"raw", "middle", "report"})
1858		assertUpstreamOnce(t, after, "a", 3, []string{"a", "z", "middle", "report"})
1859		assertUpstreamOnce(t, after, "b", 3, []string{"b", "c", "middle", "report"})
1860	}
